const $ = selector => document.querySelector(selector);
const persistence = createLocalStorageAdapter();
const boot = bootstrapState(persistence);
let state = boot.state;
let storageLocked = boot.locked;
const loadError = boot.error;
if (!storageLocked) {
  const legacyCompanion = importLegacyCompanionEntries(state, persistence.storage);
  if (legacyCompanion.imported) {
    try { state = legacyCompanion.state; persistence.save(state); }
    catch { state = legacyCompanion.state; }
  }
}
let currentScreen = 'journal';
let companionApi;
let pendingBackup = null;
let recoveryAvailable = false;
try { recoveryAvailable = Boolean(persistence.loadRecovery?.()); } catch { recoveryAvailable = false; }
const today = () => new Date().toISOString().slice(0, 10);
const esc = value => String(value ?? '').replace(/[&<>"']/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[char]));
const formatDate = value => value ? new Intl.DateTimeFormat('en', { day: 'numeric', month: 'short', year: 'numeric' }).format(new Date(value)) : 'Date not recorded';
const toast = message => { const node = $('#toast'); node.textContent = message; node.classList.add('show'); clearTimeout(toast.timer); toast.timer = setTimeout(() => node.classList.remove('show'), 2200); };
const persist = (next, { allowLocked = false } = {}) => {
  const result = persistState(persistence, next, { locked: storageLocked, allowLocked });
  if (!result.ok) { toast(result.error); return false; }
  state = result.state;
  storageLocked = false;
  renderAll();
  companionApi?.render();
  return true;
};
function openDialog(id) { $( `#${id}`).showModal(); }
function closeDialog(id) { $( `#${id}`).close(); }
function tags(value) { return String(value || '').split(',').map(item => item.trim()).filter(Boolean); }
function statusClass(status) { return String(status || '').toLowerCase(); }
function getExperiment(id) { return state.experiments.find(item => item.id === id); }

function renderJournal() {
  const query = ($('#journal-search')?.value || '').toLowerCase(); const filter = $('#journal-filter')?.value || '';
  const entries = state.journalEntries.filter(entry => { const haystack = [entry.title, entry.purpose, entry.opening, entry.heart, entry.dryDown, ...(entry.tags || []), ...(entry.descriptors || [])].join(' ').toLowerCase(); return haystack.includes(query) && (!filter || filter === (entry.measuredResults ? 'measured' : 'personal')); });
  $('#journal-result-count').textContent = `${entries.length} record${entries.length === 1 ? '' : 's'}`;
  $('#journal-list').innerHTML = entries.length ? entries.map(entry => `<article class="record" data-journal-id="${esc(entry.id)}"><div class="record-top"><div><h3>${esc(entry.title)}</h3><span class="record-date">${formatDate(entry.observedAt)} · ${esc(entry.medium || 'Medium not recorded')}</span></div><div class="record-actions"><button class="icon-button" data-action="duplicate-journal">Duplicate</button><button class="icon-button" data-action="open-journal">Open</button></div></div><p class="record-summary">${esc(entry.overall || entry.opening || entry.personalNotes || 'No sensory summary recorded yet.')}</p><div class="chips">${(entry.descriptors || []).map(item => `<span class="chip">${esc(item)}</span>`).join('')}</div></article>`).join('') : '<div class="empty-state"><strong>No entries match this view.</strong>Record an observation or adjust the search.</div>';
}

function renderExperiments() {
  const query = ($('#experiment-search')?.value || '').toLowerCase(); const status = $('#experiment-status')?.value || '';
  const experiments = state.experiments.filter(item => `${item.title} ${item.experimentId} ${item.objective}`.toLowerCase().includes(query) && (!status || item.status === status));
  $('#experiment-list').innerHTML = experiments.length ? experiments.map(experiment => { const revisions = state.revisions.filter(item => (experiment.formulaRevisionIds || []).includes(item.id)); const batches = state.batches.filter(item => (experiment.batchIds || []).includes(item.id)); return `<article class="experiment-card" data-experiment-id="${esc(experiment.id)}"><div class="experiment-meta"><span>${esc(experiment.experimentId)}</span><span class="status ${statusClass(experiment.status)}">${esc(experiment.status)}</span></div><h3>${esc(experiment.title)}</h3><p>${esc(experiment.objective || 'No objective recorded.')}</p><div class="chips"><span class="chip">${revisions.length} revision${revisions.length === 1 ? '' : 's'}</span><span class="chip">${batches.length} batch${batches.length === 1 ? '' : 'es'}</span><span class="chip">${experiment.evaluationIds?.length || 0} evaluations</span></div></article>`; }).join('') : '<div class="empty-state"><strong>No experiments yet.</strong>Create a trial to preserve its formula history.</div>';
}

function renderEvaluationJournal() {
  const query = ($('#evaluation-search')?.value || '').toLowerCase(); const provenanceFilter = $('#evaluation-provenance')?.value || '';
  const evaluations = state.evaluations.slice().sort((a, b) => String(a.evaluatedAt).localeCompare(String(b.evaluatedAt)) || a.id.localeCompare(b.id)).filter(item => {
    const provenance = item.provenance || (item.isMeasured ? 'measured' : 'subjective'); const haystack = [item.intervalLabel, item.medium, item.environment, item.conditions, item.subjectiveNotes, item.measuredResults, item.predictedOutcome, ...(item.descriptors || [])].join(' ').toLowerCase(); return haystack.includes(query) && (!provenanceFilter || provenance === provenanceFilter || (provenanceFilter === 'ai-generated' && item.aiSuggestions?.length));
  });
  $('#evaluation-timeline').innerHTML = evaluations.length ? evaluations.map(evaluation => { const experiment = getExperiment(evaluation.experimentId); const batch = state.batches.find(item => item.id === evaluation.batchId); const revision = state.revisions.find(item => item.id === evaluation.revisionId); const provenance = evaluation.provenance || (evaluation.isMeasured ? 'measured' : 'subjective'); return `<article class="record evaluation-record"><div class="record-top"><div><h3>${esc(evaluation.intervalLabel || 'Unlabelled interval')}</h3><span class="record-date">${formatDate(evaluation.evaluatedAt)}${evaluation.elapsedMinutes !== undefined ? ` · ${esc(evaluation.elapsedMinutes)} min after mixing` : ''}</span></div><span class="status ${statusClass(provenance)}">${esc(provenance)}</span></div><p class="record-summary"><strong>${esc(experiment?.title || evaluation.experimentId)}</strong> · ${esc(batch?.batchCode || 'Batch not recorded')} · Revision ${esc(revision?.revision || '?')}</p><div class="chips">${(evaluation.descriptors || []).map(item => `<span class="chip">${esc(item)}</span>`).join('')}</div><p><strong>Subjective:</strong> ${esc(evaluation.subjectiveNotes || 'Not recorded')}</p>${evaluation.measuredResults ? `<p><strong>Measured:</strong> ${esc(evaluation.measuredResults)}</p>` : '<p class="muted"><strong>Measured:</strong> Not recorded</p>'}${evaluation.predictedOutcome ? `<p class="muted"><strong>Predicted:</strong> ${esc(evaluation.predictedOutcome)}</p>` : ''}<p class="muted">${esc(evaluation.medium || 'Medium unknown')} · ${esc(evaluation.environment || 'Environment unknown')} · ${esc(evaluation.conditions || 'Conditions not recorded')}</p>${evaluation.longevityObservation || evaluation.projectionObservation ? `<p class="muted">Longevity: ${esc(evaluation.longevityObservation || 'Not recorded')}${evaluation.longevityMethod ? ` (${esc(evaluation.longevityMethod)})` : ''} · Projection: ${esc(evaluation.projectionObservation || 'Not recorded')}${evaluation.projectionMethod ? ` (${esc(evaluation.projectionMethod)})` : ''}</p>` : ''}</article>`; }).join('') : '<div class="empty-state"><strong>No evaluations match this view.</strong>Record a sensory evaluation from a physical batch, or adjust the filters.</div>';
}

function coachOptions(items, current, label) { return `<option value="">${label}</option>${items.map(item => `<option value="${esc(item.id)}" ${item.id === current ? 'selected' : ''}>${esc(item.label)}</option>`).join('')}`; }
function renderCoachControls() {
  const experimentSelect = $('#coach-experiment'); const revisionSelect = $('#coach-revision'); const batchSelect = $('#coach-batch'); if (!experimentSelect) return;
  const currentExperiment = experimentSelect.value || state.experiments[0]?.id || '';
  experimentSelect.innerHTML = coachOptions(state.experiments.map(item => ({ id: item.id, label: `${item.experimentId} · ${item.title}` })), currentExperiment, 'Choose experiment');
  const experiment = state.experiments.find(item => item.id === experimentSelect.value) || state.experiments[0];
  if (!experiment) { revisionSelect.innerHTML = '<option value="">All revisions</option>'; batchSelect.innerHTML = '<option value="">All batches</option>'; return; }
  const revisions = state.revisions.filter(item => (experiment.formulaRevisionIds || []).includes(item.id)).map(item => ({ id: item.id, label: `Revision ${item.revision} · ${item.notes || 'No notes'}` }));
  const batches = state.batches.filter(item => (experiment.batchIds || []).includes(item.id)).map(item => ({ id: item.id, label: `${item.batchCode} · Revision ${state.revisions.find(revision => revision.id === item.formulaRevisionId)?.revision || '?'}` }));
  revisionSelect.innerHTML = coachOptions(revisions, revisionSelect.value, 'All revisions');
  batchSelect.innerHTML = coachOptions(batches, batchSelect.value, 'All physical batches');
}
function coachClaimHtml(item) { return `<article class="record coach-claim"><p>${esc(item.text)}</p><small class="muted">${esc(item.evidenceClass || 'recorded')} · Sources: ${item.sourceIds.map(sourceId => `<code>${esc(sourceId)}</code>`).join(', ')}</small></article>`; }
function renderCoachDebrief(debrief) {
  const claimSections = [['Experiment', debrief.claims.experiment], ['Formula revisions', debrief.claims.revisions], ['Physical batches', debrief.claims.batches], ['Sensory timeline', debrief.claims.sensoryTimeline]].map(([heading, claims]) => `<section><p class="label">${heading.toUpperCase()}</p>${claims.length ? claims.map(coachClaimHtml).join('') : '<p class="muted">No linked records.</p>'}</section>`).join('');
  const revisionSection = debrief.claims.revisionComparisons.length ? `<section><p class="label">FORMULA REVISION DIFFERENCES</p>${debrief.claims.revisionComparisons.map(item => `<article class="record coach-claim"><p><strong>${esc(item.leftRevisionId)}</strong> → <strong>${esc(item.rightRevisionId)}</strong>: ${item.ingredientChanges.length ? esc(item.ingredientChanges.map(change => `${change.kind} ${change.key}`).join(', ')) : 'No ingredient changes recorded.'}</p>${item.warnings.length ? `<p class="muted">${item.warnings.map(warning => esc(warning)).join(' ')}</p>` : ''}<small class="muted">Sources: ${item.sourceIds.map(sourceId => `<code>${esc(sourceId)}</code>`).join(', ')}</small></article>`).join('')}</section>` : '';
  const missing = debrief.missingEvidence.length ? `<section class="coach-warning"><p class="label">MISSING OR CONTRADICTORY EVIDENCE</p><ul>${debrief.missingEvidence.map(item => `<li>${esc(item.warning || item.claim || 'Evidence issue')} · <code>${esc(item.sourceId || 'context')}</code></li>`).join('')}</ul></section>` : '<p class="inventory-ok">No missing or contradictory evidence was detected in the selected records.</p>';
  const proposal = debrief.proposedNextExperiment;
  $('#coach-output').innerHTML = `<div class="coach-result"><div class="coach-readonly"><strong>Read-only debrief.</strong> Nothing here changes formulas, stock, batches, or observations.</div><h2>${esc(debrief.title)}</h2>${claimSections}${revisionSection}${missing}<section><p class="label">PROPOSED NEXT CONTROLLED EXPERIMENT</p><div class="record"><p><strong>Hypothesis:</strong> ${esc(proposal.hypothesis.text)}</p><p><strong>Primary variable:</strong> ${esc(proposal.primaryVariable.text)}</p><p><strong>Observation schedule:</strong> ${proposal.observationSchedule.map(item => esc(item.label)).join(' · ')}</p><p><strong>Success criterion:</strong> ${esc(proposal.successCriterion.text)}</p><p class="muted">${esc(proposal.note)}</p><small class="muted">Sources: ${proposal.hypothesis.sourceIds.map(sourceId => `<code>${esc(sourceId)}</code>`).join(', ')}</small></div></section><p class="muted">${esc(debrief.disclaimer)}</p></div>`;
}
function runCoach() { try { const context = buildExperimentCoachContext(state, { experimentId: $('#coach-experiment').value, revisionId: $('#coach-revision').value || undefined, batchId: $('#coach-batch').value || undefined }); renderCoachDebrief(createExperimentCoachDebrief(context)); } catch (error) { $('#coach-output').innerHTML = `<div class="empty-state"><strong>Coach could not build this debrief.</strong><p>${esc(error.message)}</p></div>`; } }

function renderMaterials() {
  const summary = inventorySummary(state);
  $('#inventory-summary').innerHTML = [['LOTS', summary.lots.length], ['KNOWN ON-HAND', summary.lots.filter(item => item.balanceKnown).length], ['RECONCILIATION NEEDED', summary.unknownLots.length], ['LOW STOCK / DATE WARNINGS', summary.lowStock.length + summary.dateWarnings.length]].map(([label, value]) => `<div><span>${label}</span><strong>${value}</strong></div>`).join('');
  const warnings = [...summary.unknownLots.map(item => `<div class="inventory-warning"><strong>${esc(item.materialName)} · ${esc(item.lot.lotCode || item.lot.id)}</strong><span>Opening quantity unknown. ${item.balance == null ? 'No compatible quantity is recorded yet.' : `Recorded balance ${item.balance.toFixed(4)} ${esc(item.unit)} is a consumption floor, not measured on-hand stock.`}</span></div>`), ...summary.lowStock.map(item => `<div class="inventory-warning"><strong>Low stock · ${esc(item.materialName)} · ${esc(item.lot.lotCode || item.lot.id)}</strong><span>${item.balance.toFixed(4)} ${esc(item.unit)} at or below threshold ${esc(item.lot.lowStockThreshold)} ${esc(item.unit)}.</span></div>`), ...summary.dateWarnings.map(item => `<div class="inventory-warning"><strong>Date reminder · ${esc(item.materialName)} · ${esc(item.lot.lotCode || item.lot.id)}</strong><span>${esc(item.warnings.filter(warning => warning.includes('date')).join(' '))} Operational reminder only; not a safety determination.</span></div>`)].join('');
  $('#inventory-warnings').innerHTML = warnings || '<div class="inventory-ok">No inventory warnings for recorded dates, thresholds, or opening balances.</div>';
  $('#material-list').innerHTML = state.materials.length ? `<table><thead><tr><th>MATERIAL</th><th>LOT / ON-HAND</th><th>IDENTITY &amp; STORAGE</th><th>HISTORY</th><th>ACTIONS</th></tr></thead><tbody>${state.materials.map(material => { const lots = material.lots || []; const used = state.batches.flatMap(batch => batch.actualAdditions || []).filter(addition => addition.materialId === material.id).length; return `<tr><td><strong>${esc(material.name)}</strong><br><span class="muted">${esc(material.supplier || 'Supplier not recorded')} · ${used} batch use${used === 1 ? '' : 's'}</span></td><td>${lots.length ? lots.map(lot => { const status = stockStatus(state, lot.id); const unit = status.unit || '?'; const history = lotMovementHistory(state, lot.id); const label = lot.lotCode || lot.id; const balance = status.balanceKnown ? `${status.balance.toFixed(4)} ${esc(unit)}` : `Unknown${status.balance == null ? '' : ` · floor ${status.balance.toFixed(4)} ${esc(unit)}`}`; return `<div class="lot-ledger"><div class="lot-meta"><strong>${esc(label)}</strong><small>${esc(lot.receivedAt || 'Received date not recorded')} · ${lot.purity == null ? 'Purity unknown' : `${lot.purity}% purity`} · ${lot.expiryDate ? `Expiry ${esc(lot.expiryDate)}` : 'Expiry unknown'}</small><span class="${status.balanceKnown ? '' : 'unknown-stock'}">On-hand: ${balance}</span></div><div class="inventory-actions"><button class="icon-button" data-action="new-movement" data-material-id="${esc(material.id)}" data-lot-id="${esc(lot.id)}" type="button">Movement</button><button class="icon-button" data-action="reconcile-lot" data-lot-id="${esc(lot.id)}" type="button">Reconcile</button></div><details><summary>${history.length} movement${history.length === 1 ? '' : 's'} · ${history.filter(item => item.batchId).length} linked batch${history.filter(item => item.batchId).length === 1 ? '' : 'es'}</summary><ol class="ledger-history">${history.map(movement => { const sign = ['opening', 'receipt', 'return'].includes(movement.movementType) || (['adjustment', 'correction'].includes(movement.movementType) && movement.direction === 'increase') ? '+' : '-'; const batch = movement.batchId ? state.batches.find(item => item.id === movement.batchId) : null; return `<li><span class="${sign === '+' ? 'movement-positive' : 'movement-negative'}">${sign}${esc(movement.quantity)} ${esc(movement.unit)}</span> · ${esc(movement.movementType)} · ${formatDate(movement.occurredAt)}${batch ? ` · ${esc(batch.batchCode)}` : ''}${movement.note ? ` · ${esc(movement.note)}` : ''}</li>`; }).join('')}</ol></details></div>`; }).join('') : '<span class="muted">No lots recorded.</span>'}</td><td><div>${esc(material.canonicalIdentity || 'Identity not recorded')}</div><small class="muted">${esc(material.productReference || 'Product reference not recorded')}<br>${esc(material.storageNotes || 'Storage notes not recorded')}<br>${esc(material.safetyReference || 'Safety reference not recorded')}</small></td><td>${lots.reduce((sum, lot) => sum + lotMovementHistory(state, lot.id).length, 0)} movements</td><td><div class="inventory-actions"><button class="icon-button" data-action="new-lot" data-material-id="${esc(material.id)}" type="button">Add lot</button><button class="icon-button" data-action="new-movement" data-material-id="${esc(material.id)}" type="button">Record movement</button></div></td></tr>`; }).join('')}</tbody></table>` : '<div class="empty-state"><strong>No materials recorded.</strong>Add only what you know; unknown supplier, quantity, and chemical properties stay visible as unknown.</div>';
  $('#recent-movements').innerHTML = summary.recentMovements.length ? summary.recentMovements.map(movement => `<article class="record"><div class="record-top"><strong>${esc(movement.movementType)}</strong><span class="record-date">${formatDate(movement.occurredAt)} · ${esc(movement.quantity)} ${esc(movement.unit)}</span></div><p class="record-summary">${esc(movement.note || 'No reason recorded.')}${movement.batchId ? ` · Batch ${esc(state.batches.find(batch => batch.id === movement.batchId)?.batchCode || movement.batchId)}` : ''}</p></article>`).join('') : '<div class="empty-state">No ledger movements yet.</div>';
}

function renderEquipment() {
  const query = ($('#equipment-search')?.value || '').toLowerCase(); const statusFilter = $('#equipment-status-filter')?.value || ''; const verificationFilter = $('#equipment-verification-filter')?.value || '';
  const records = equipmentSummary(state).filter(record => { const item = record.equipment; const haystack = [item.name, item.equipmentType, item.manufacturer, item.model, item.serialNumber, item.location].join(' ').toLowerCase(); return haystack.includes(query) && (!statusFilter || item.status === statusFilter) && (!verificationFilter || record.verification.status === verificationFilter); });
  const all = equipmentSummary(state); const counts = { total: all.length, verified: all.filter(item => ['verified', 'conditional'].includes(item.verification.status)).length, warnings: all.filter(item => item.warnings.length).length, measurements: state.measurements.length };
  $('#equipment-summary').innerHTML = [['EQUIPMENT', counts.total], ['VERIFIED / CONDITIONAL', counts.verified], ['ACTIVE WARNINGS', counts.warnings], ['MEASUREMENTS', counts.measurements]].map(([label, value]) => `<div><span>${label}</span><strong>${value}</strong></div>`).join('');
  $('#equipment-warnings').innerHTML = all.flatMap(record => record.warnings.map(warning => `<div class="inventory-warning"><strong>${esc(record.equipment.name)}</strong><span>${esc(warning)}</span></div>`)).join('') || '<div class="inventory-ok">No equipment warnings. Unknown verification remains visible when no evidence is recorded.</div>';
  $('#equipment-list').innerHTML = records.length ? records.map(record => { const item = record.equipment; const verification = record.verification; const history = [...record.maintenance.map(event => ({ ...event, kind: event.eventType, date: event.occurredAt })), ...record.verification.events.map(event => ({ ...event, kind: `verification: ${event.outcome}`, date: event.performedAt }))].sort((a, b) => String(b.date).localeCompare(String(a.date))); return `<article class="record equipment-card" data-equipment-id="${esc(item.id)}"><div class="record-top"><div><p class="label">${esc(item.equipmentType)} · ${esc(item.location || 'Location not recorded')}</p><h2>${esc(item.name)}</h2><span class="record-date">${esc(item.manufacturer || 'Manufacturer unknown')}${item.model ? ` · ${esc(item.model)}` : ''}${item.serialNumber ? ` · S/N ${esc(item.serialNumber)}` : ''}</span></div><span class="status ${statusClass(item.status)}">${esc(item.status)}</span></div><div class="chips"><span class="chip">Verification: ${esc(verification.status)}</span>${item.resolution ? `<span class="chip">Resolution ${esc(item.resolution)} ${esc(item.resolutionUnit || '')}</span>` : '<span class="chip unknown-stock">Resolution unknown</span>'}<span class="chip">${record.measurements.length} measurement${record.measurements.length === 1 ? '' : 's'}</span></div>${record.warnings.length ? `<p class="unknown-stock">${record.warnings.map(warning => esc(warning)).join(' ')}</p>` : '<p class="inventory-ok">No current warnings.</p>'}<div class="form-actions"><button class="icon-button" data-action="edit-equipment" data-id="${esc(item.id)}">Edit</button><button class="icon-button" data-action="new-verification" data-id="${esc(item.id)}">Verification</button><button class="icon-button" data-action="new-maintenance" data-id="${esc(item.id)}">Maintenance</button><button class="icon-button" data-action="new-measurement" data-id="${esc(item.id)}">Measurement</button></div><details><summary>${history.length} history event${history.length === 1 ? '' : 's'} · ${record.measurements.length} linked measurement${record.measurements.length === 1 ? '' : 's'}</summary><div class="ledger-history">${history.map(event => `<p><strong>${esc(event.kind)}</strong> · ${formatDate(event.date)}${event.notes ? ` · ${esc(event.notes)}` : ''}</p>`).join('') || '<p class="muted">No history recorded.</p>'}${record.measurements.map(measurement => `<p><strong>measurement</strong> · ${formatDate(measurement.measuredAt)} · ${esc(measurement.quantityType)} ${esc(measurement.value)} ${esc(measurement.unit)}${measurement.method ? ` · ${esc(measurement.method)}` : ''}</p>`).join('')}</div></details></article>`; }).join('') : '<div class="empty-state"><strong>No equipment matches this view.</strong><p>Register the equipment before recording verification or measurements.</p></div>';
}

function renderPurchases() {
  const purchases = state.purchases.slice().sort((a, b) => String(b.purchaseDate).localeCompare(String(a.purchaseDate)) || b.id.localeCompare(a.id));
  const summaries = purchases.map(purchase => purchaseSummary(state, purchase.id)); const unverified = summaries.filter(summary => !summary.receiptVerified).length; const uncosted = state.batches.reduce((sum, batch) => sum + calculateBatchCost(state, batch.id).uncosted.length, 0);
  $('#purchase-summary').innerHTML = [['PURCHASES', purchases.length], ['RECEIPT-VERIFIED', summaries.filter(summary => summary.receiptVerified).length], ['UNVERIFIED PRICES', unverified], ['UNCOSTED ADDITIONS', uncosted]].map(([label, value]) => `<div><span>${label}</span><strong>${value}</strong></div>`).join('');
  $('#purchase-warnings').innerHTML = summaries.filter(summary => !summary.receiptVerified).map(summary => `<div class="inventory-warning"><strong>${esc(summary.purchase.supplier)} · ${esc(summary.purchase.receiptNumber || summary.purchase.id)}</strong><span>Price recorded without receipt evidence; it is not receipt-verified and will not contribute to a complete batch cost.</span></div>`).join('') || '<div class="inventory-ok">All recorded purchase prices have receipt evidence.</div>';
  $('#purchase-list').innerHTML = purchases.length ? purchases.map(purchase => { const summary = purchaseSummary(state, purchase.id); const lineNames = summary.lineItems.map(line => { const material = state.materials.find(item => item.id === line.materialId); const lot = material?.lots?.find(item => item.id === line.materialLotId); return `<li><strong>${esc(material?.name || line.materialId)}</strong> · ${esc(line.quantity)} ${esc(line.unit)} · ${esc(line.unitPrice)} ${esc(purchase.currency)}/${esc(line.unit)} · line ${esc(line.lineTotal)} ${esc(purchase.currency)} · lot ${esc(lot?.lotCode || line.materialLotId)}</li>`; }).join(''); return `<article class="record"><div class="record-top"><div><p class="label">${esc(purchase.purchaseDate)} · ${esc(purchase.currency)}</p><h2>${esc(purchase.supplier)}</h2><span class="record-date">${esc(purchase.receiptNumber || 'Receipt reference not recorded')} · ${summary.receiptVerified ? 'Receipt evidence attached' : 'Receipt evidence missing'}</span></div><span class="status ${summary.receiptVerified ? 'verified' : 'unknown-stock'}">${summary.receiptVerified ? 'receipt-verified' : 'unverified'}</span></div><div class="chips"><span class="chip">Subtotal ${esc(summary.subtotal.toFixed(2))} ${esc(purchase.currency)}</span><span class="chip">Total ${esc(summary.total.toFixed(2))} ${esc(purchase.currency)}</span><span class="chip">${summary.lineItems.length} line${summary.lineItems.length === 1 ? '' : 's'}</span></div><ul>${lineNames}</ul><p class="muted">${esc(purchase.notes || 'No purchase notes recorded.')}</p><div class="form-actions"><button class="icon-button" data-action="edit-purchase" data-id="${esc(purchase.id)}">Edit purchase</button></div></article>`; }).join('') : '<div class="empty-state"><strong>No purchases recorded.</strong><p>Add receipt-backed purchase lines before expecting a complete batch cost.</p></div>';
}

function renderCompare() {
  const records = state.revisions.map(revision => { const experiment = getExperiment(revision.experimentId); return { value: revision.id, label: `${experiment?.experimentId || 'Experiment'} · Revision ${revision.revision} · ${experiment?.title || ''}`, revision, experiment }; });
  const options = records.map(record => `<option value="${esc(record.value)}">${esc(record.label)}</option>`).join(''); const a = $('#compare-a'); const b = $('#compare-b');
  const previousA = a.value; const previousB = b.value; a.innerHTML = options; b.innerHTML = options; a.value = records.some(record => record.value === previousA) ? previousA : records[0]?.value || ''; b.value = records.some(record => record.value === previousB) ? previousB : records[1]?.value || records[0]?.value || '';
  if (records.length < 2) { $('#comparison').innerHTML = '<div class="empty-state"><strong>Two revisions make a comparison.</strong>Create another formula revision to see changes side by side.</div>'; return; }
  const first = state.revisions.find(item => item.id === a.value) || state.revisions[0]; const second = state.revisions.find(item => item.id === b.value) || state.revisions[1];
  const comparison = compareRevisions(state, first.id, second.id);
  const changes = comparison.ingredientChanges.length ? comparison.ingredientChanges.map(change => `<li>${esc(change.kind)} · ${esc(change.after?.materialName || change.before?.materialName || change.key)}</li>`).join('') : '<li>No ingredient changes recorded.</li>';
  $('#comparison').innerHTML = [first, second].map(revision => { const experiment = getExperiment(revision.experimentId); const evaluations = revision.id === first.id ? comparison.leftEvaluations : comparison.rightEvaluations; const batches = revision.id === first.id ? comparison.leftBatchTotals : comparison.rightBatchTotals; return `<article class="comparison-card"><p class="label">REVISION ${revision.revision} · ${esc(experiment?.experimentId || '')}</p><h2>${esc(experiment?.title || 'Untitled experiment')}</h2><p>${esc(revision.notes || 'No revision notes recorded.')}</p><h3>INGREDIENTS</h3>${revision.ingredients?.length ? `<div class="chips">${revision.ingredients.map(item => `<span class="chip">${esc(item.materialName || item.materialId)} · ${esc(item.quantity)} ${esc(item.unit)}${item.lotId ? ` · lot ${esc(item.lotId)}` : ''}</span>`).join('')}</div>` : '<p>No ingredients recorded.</p>'}<h3>ACTUAL BATCHES</h3><p>${batches.length ? batches.map(batch => `${esc(batch.batchId)}: planned ${esc(batch.plannedAmount)} ${esc(batch.plannedUnit)}, actual ${batch.actual ? esc(batch.actual.totalAmount) : 'not recorded'} ${esc(batch.actual?.unit || batch.plannedUnit)}`).join('<br>') : 'No actual batch recorded.'}</p><h3>RECORDED EVIDENCE</h3><p>${evaluations.length} linked evaluation${evaluations.length === 1 ? '' : 's'} · ${evaluations.filter(item => item.isMeasured).length} marked measured · ${evaluations.filter(item => !item.isMeasured).length} subjective</p></article>`; }).join('') + `<div class="compare-note"><strong>Recorded ingredient changes</strong><ul>${changes}</ul>${comparison.warnings.length ? `<p>${comparison.warnings.map(warning => esc(warning)).join(' ')}</p>` : ''}<span>A changed score or descriptor is a recorded difference, not proof that one formula caused it. Compare conditions and evaluation intervals before drawing conclusions.</span></div>`;
}

function renderAll() { $('#stat-journal').textContent = state.journalEntries.length; $('#stat-experiments').textContent = state.experiments.filter(item => item.status !== 'Archived').length; $('#stat-maturing').textContent = state.experiments.filter(item => item.status === 'Maturing').length; $('#stat-evaluations').textContent = state.evaluations.length; const banner = $('#recovery-banner'); if (banner) { banner.hidden = !storageLocked; $('#recovery-message').textContent = loadError || 'Saved data is unreadable.'; } renderJournal(); renderExperiments(); renderEvaluationJournal(); renderCoachControls(); try { renderMaterials(); renderEquipment(); renderPurchases(); } catch (error) { console.error(error); $('#material-list').innerHTML = `<div class="empty-state"><strong>Inventory could not render.</strong>${esc(error.message)}</div>`; } renderCompare(); companionApi?.render(); }

function journalFormValues(form) { const values = Object.fromEntries(new FormData(form)); return { title: values.title, observedAt: new Date(`${values.observedAt}T12:00:00`).toISOString(), experimentId: values.experimentId || undefined, medium: values.medium, evaluationTimeMinutes: values.evaluationTimeMinutes ? Number(values.evaluationTimeMinutes) : undefined, purpose: values.purpose, hypothesis: values.purpose, opening: values.opening, heart: values.heart, dryDown: values.dryDown, overall: values.dryDown, descriptors: tags(values.descriptors), tags: tags(values.tags), intensity: values.intensity ? Number(values.intensity) : undefined, projection: values.projection ? Number(values.projection) : undefined, personalNotes: values.personalNotes, attachmentRefs: [] }; }
function showJournalForm(entry = null) { const form = $('#journal-form'); form.reset(); form.dataset.editId = entry?.id || ''; form.elements.experimentId.innerHTML = '<option value="">Not linked</option>' + state.experiments.map(item => `<option value="${esc(item.id)}">${esc(item.experimentId)} · ${esc(item.title)}</option>`).join(''); form.elements.observedAt.value = entry?.observedAt?.slice(0, 10) || today(); if (entry) for (const key of ['title', 'medium', 'purpose', 'opening', 'heart', 'dryDown', 'personalNotes', 'experimentId']) if (entry[key] != null && form.elements[key]) form.elements[key].value = entry[key]; form.elements.descriptors.value = entry?.descriptors?.join(', ') || ''; form.elements.tags.value = entry?.tags?.join(', ') || ''; form.elements.evaluationTimeMinutes.value = entry?.evaluationTimeMinutes || ''; form.elements.intensity.value = entry?.intensity || ''; form.elements.projection.value = entry?.projection || ''; $('#journal-dialog h2').textContent = entry ? 'Edit journal entry' : 'New journal entry'; openDialog('journal-dialog'); }

