function showEvaluationForm(experimentId) { const experiment = getExperiment(experimentId); const batches = state.batches.filter(item => experiment.batchIds.includes(item.id)); $('#record-dialog-content').innerHTML = `<form id="evaluation-form" class="dialog-content" data-experiment-id="${esc(experimentId)}"><p class="label">SENSORY EVALUATION</p><h2>Record an observation</h2><div class="form-grid"><label>Interval label<input name="intervalLabel" placeholder="e.g. 24 hours"></label><label>Medium<select name="medium"><option>Blotter</option><option>Skin</option><option>Other</option></select></label><label>Batch<select name="batchId">${batches.map(item => `<option value="${esc(item.id)}">${esc(item.batchCode)}</option>`).join('')}</select></label><label>Evaluation date<input name="evaluatedAt" type="date" value="${today()}"></label></div><label>Descriptors<input name="descriptors" placeholder="green, woody, soft"></label><label>Subjective notes<textarea name="subjectiveNotes" rows="3"></textarea></label><label>Measured results (optional; include method)<textarea name="measuredResults" rows="3"></textarea></label><div class="form-actions"><button type="button" class="text-button" data-action="back-experiment" data-id="${esc(experimentId)}">Cancel</button><button class="primary-button">Save evaluation</button></div></form>`; }

function batchAdditionRow(index, values = {}) {
  const materials = state.materials.map(material => `<option value="${esc(material.id)}" ${material.id === values.materialId ? 'selected' : ''}>${esc(material.name)}</option>`).join('');
  const material = state.materials.find(item => item.id === (values.materialId || state.materials[0]?.id));
  const lots = (material?.lots || []).map(lot => `<option value="${esc(lot.id)}" ${lot.id === values.materialLotId ? 'selected' : ''}>${esc(lot.lotCode || lot.id)} · ${esc(lot.receivedUnit || stockStatus(state, lot.id).unit || '?')}</option>`).join('');
  return `<div class="batch-addition-row" data-addition-index="${index}"><div class="form-grid"><label>Material<select name="materialId" data-role="addition-material" required>${materials}</select></label><label>Physical lot<select name="materialLotId" data-role="addition-lot" required>${lots}</select></label><label>Actual quantity<input name="amount" type="number" min="0.0001" step="0.0001" value="${esc(values.amount ?? '')}" required></label><label>Unit<select name="unit"><option value="mg" ${values.unit === 'mg' ? 'selected' : ''}>mg</option><option value="g" ${values.unit === 'g' || !values.unit ? 'selected' : ''}>g</option><option value="kg" ${values.unit === 'kg' ? 'selected' : ''}>kg</option><option value="mL" ${values.unit === 'mL' ? 'selected' : ''}>mL</option><option value="L" ${values.unit === 'L' ? 'selected' : ''}>L</option></select></label><label>Receipt price<select name="purchaseLineItemId">${purchaseLineOptions(values.materialLotId, values.purchaseLineItemId)}</select></label><label>Concentration (%)<input name="concentration" type="number" min="0" max="100" step="0.01" value="${esc(values.concentration ?? 100)}"></label><label>Added at<input name="addedAt" type="datetime-local" value="${esc(values.addedAt || '')}"></label></div><button type="button" class="text-button" data-action="remove-batch-addition">Remove addition</button></div>`;
}

function renderBatchAdditionRows(form, rows) { $('#batch-additions').innerHTML = rows.map((values, index) => batchAdditionRow(index, values)).join(''); }

function showBatchForm(experimentId) {
  const experiment = getExperiment(experimentId); const revisions = state.revisions.filter(item => experiment.formulaRevisionIds.includes(item.id)); const revision = revisions.at(-1);
  const seedRows = (revision?.ingredients || []).map(ingredient => ({ materialId: ingredient.materialId, materialLotId: ingredient.lotId || state.materials.find(item => item.id === ingredient.materialId)?.lots?.[0]?.id, amount: ingredient.quantity, unit: ingredient.unit, concentration: ingredient.stockConcentration ?? 100 }));
  $('#record-dialog-content').innerHTML = `<form id="batch-form" class="dialog-content" data-experiment-id="${esc(experimentId)}"><p class="label">PHYSICAL BATCH · TRACEABLE</p><h2>Record what was actually mixed</h2><p class="muted"><strong>${esc(experiment.experimentId)} · ${esc(experiment.title)}</strong><br>Choose one exact formula revision. Planned quantities remain unchanged; each row below creates one lot-specific stock consumption.</p><div class="form-grid"><label>Formula revision<select name="formulaRevisionId" id="batch-form-revision">${revisions.map(item => `<option value="${esc(item.id)}" ${item.id === revision?.id ? 'selected' : ''}>Revision ${item.revision} · ${esc(item.notes || 'No notes')}</option>`).join('')}</select></label><label>Batch identifier<input name="batchCode" required placeholder="BATCH-004"></label><label>Planned batch size<input name="plannedAmount" type="number" min="0.0001" step="0.0001" required></label><label>Unit<select name="unit"><option>mg</option><option selected>g</option><option>kg</option><option>mL</option><option>L</option></select></label><label>Mixing date/time<input name="mixingDate" type="datetime-local" required></label></div><div class="section-heading"><div><p class="label">ACTUAL ADDITIONS</p><h3>One row per physical addition</h3></div><button type="button" class="secondary-button" data-action="add-batch-addition">＋ Add row</button></div><div id="batch-additions"></div><label>Procedure notes<textarea name="procedureNotes" rows="3" placeholder="Order of addition, temperature, mixing method…"></textarea></label><label>Relevant observations<textarea name="observations" rows="2" placeholder="Appearance, clarity, unexpected behavior…"></textarea></label><label>Deviations from plan<textarea name="deviations" rows="2" placeholder="Record deviations; do not edit the formula revision."></textarea></label><div class="form-actions"><button type="button" class="text-button" data-action="back-experiment" data-id="${esc(experimentId)}">Cancel</button><button class="primary-button">Append physical batch</button></div></form>`;
  const form = $('#batch-form'); form.elements.plannedAmount.value = revision?.ingredients?.reduce((sum, item) => item.unit === (revision.ingredients[0]?.unit || 'g') ? sum + item.quantity : sum, 0) || ''; form.elements.mixingDate.value = new Date().toISOString().slice(0, 16); renderBatchAdditionRows(form, seedRows.length ? seedRows : [{}]);

  openDialog("record-dialog");
}

function showBatchDetail(batchId, experimentId) {
  const batch = state.batches.find(item => item.id === batchId); const experiment = getExperiment(experimentId || batch?.experimentId); if (!batch || !experiment) return;
  const revision = state.revisions.find(item => item.id === batch.formulaRevisionId); const comparison = compareBatchToPlan(state, batch.id); const summary = batchSummary(batch); const rowStatus = row => row.status === 'missing' ? 'Missing' : row.status === 'deviates' ? 'Deviation' : 'Matched';
  $('#record-dialog-content').innerHTML = `<div class="dialog-content"><p class="label">${esc(experiment.experimentId)} · PHYSICAL BATCH</p><h2>${esc(batch.batchCode)}</h2><p class="record-summary">Revision ${esc(revision?.revision || '?')} · mixed ${formatDate(batch.mixingDate)} · planned ${esc(batch.plannedAmount)} ${esc(batch.unit)} · actual ${esc(summary.totalAmount.toFixed(4))} ${esc(summary.unit)}</p><div class="chips"><span class="chip">${comparison.totalDifference >= 0 ? '+' : ''}${comparison.totalDifference.toFixed(4)} ${esc(comparison.unit)} vs formula ingredients</span><span class="chip">${batch.actualAdditions.length} actual additions</span><span class="chip">${batch.actualAdditions.filter(item => item.stockMovementId).length} linked movements</span></div><h3>PLANNED VS ACTUAL</h3><div class="table-wrap"><table><thead><tr><th>PLANNED MATERIAL</th><th>PLANNED</th><th>ACTUAL</th><th>DIFFERENCE</th><th>STATUS</th></tr></thead><tbody>${comparison.rows.map(row => `<tr><td>${esc(row.materialName)}${row.lotId ? `<br><small class="muted">Lot ${esc(lotMovementHistory(state, row.lotId)[0]?.materialLotId || row.lotId)}</small>` : ''}</td><td>${esc(row.amountInBatchUnit.toFixed(4))} ${esc(comparison.unit)}</td><td>${esc(row.actualAmount.toFixed(4))} ${esc(comparison.unit)}</td><td>${row.difference >= 0 ? '+' : ''}${esc(row.difference.toFixed(4))} ${esc(comparison.unit)}</td><td>${rowStatus(row)}</td></tr>`).join('')}${comparison.extraAdditions.map(addition => `<tr><td>${esc(addition.materialName)}<br><small class="muted">Extra · lot ${esc(addition.lotCode)}</small></td><td>—</td><td>${esc(addition.amountInBatchUnit.toFixed(4))} ${esc(comparison.unit)}</td><td>+${esc(addition.amountInBatchUnit.toFixed(4))} ${esc(comparison.unit)}</td><td>Extra</td></tr>`).join('')}</tbody></table></div><h3>ACTUAL LOT USE</h3><ul>${batch.actualAdditions.map(addition => { const material = state.materials.find(item => item.id === addition.materialId); const lot = material?.lots?.find(item => item.id === addition.materialLotId); const movement = state.stockMovements.find(item => item.id === addition.stockMovementId); return `<li>${esc(material?.name || addition.materialId)} · lot ${esc(lot?.lotCode || addition.materialLotId)} · ${esc(addition.amount)} ${esc(addition.unit)} · movement ${esc(movement?.id || addition.stockMovementId)}</li>`; }).join('')}</ul><h3>PROCESS RECORD</h3><p>${esc(batch.procedureNotes || 'No procedure notes recorded.')}</p><p>${esc(batch.observations || 'No relevant observations recorded.')}</p><p><strong>Deviations:</strong> ${esc(batch.deviations || 'None recorded.')}</p><div class="form-actions"><button type="button" class="text-button" data-action="back-experiment" data-id="${esc(experiment.id)}">Back to experiment</button></div></div>`;
}

