function showSensoryEvaluationForm(experimentId) {
  const experiment = getExperiment(experimentId); const batches = state.batches.filter(item => experiment.batchIds.includes(item.id));
  $('#record-dialog-content').innerHTML = `<form id="evaluation-form" class="dialog-content" data-experiment-id="${esc(experimentId)}"><p class="label">SENSORY JOURNAL · TRACEABLE</p><h2>Record a batch evaluation</h2><p class="muted">Subjective impressions, measured observations, predictions, and AI suggestions remain separate. Missing fields stay unrecorded.</p><div class="form-grid"><label>Physical batch<select name="batchId" required>${batches.map(item => `<option value="${esc(item.id)}">${esc(item.batchCode)} · Revision ${esc(state.revisions.find(revision => revision.id === item.formulaRevisionId)?.revision || '?')}</option>`).join('')}</select></label><label>Evaluation date/time<input name="evaluatedAt" type="datetime-local" required></label><label>Elapsed after mixing (minutes)<input name="elapsedMinutes" type="number" min="0" step="1" placeholder="e.g. 1440"></label><label>Interval label<input name="intervalLabel" required placeholder="Opening, 24 hours, dry-down…"></label><label>Medium<input name="medium" placeholder="Blotter, skin, strip…"></label><label>Environment<input name="environment" placeholder="Room, temperature, humidity…"></label></div><label>Relevant conditions<textarea name="conditions" rows="2" placeholder="Application amount, dilution, evaluator, or other conditions."></textarea><label>Descriptors<input name="descriptors" placeholder="green, woody, soft"></label><label>Subjective sensory observations<textarea name="subjectiveNotes" rows="4" placeholder="What was experienced? Keep this separate from measurement."></textarea></label><div class="form-grid"><label>Longevity observation<input name="longevityObservation" placeholder="e.g. present at 6 hours"></label><label>Longevity method / basis<input name="longevityMethod" placeholder="estimated on skin, timed blotter check…"></label><label>Projection observation<input name="projectionObservation" placeholder="e.g. close to skin after 2 hours"></label><label>Projection method / basis<input name="projectionMethod" placeholder="estimated, panel observation…"></label></div><label class="check-row"><input name="isMeasured" type="checkbox"> This entry includes measured results</label><label>Measured results<textarea name="measuredResults" rows="3" placeholder="Method and result only; leave blank when not measured."></textarea></label><label>Predicted outcome <span class="optional">optional, not observed</span><textarea name="predictedOutcome" rows="2" placeholder="What was expected before or during the trial?"></textarea></label><label>Conclusions<textarea name="conclusions" rows="2" placeholder="What can be said from this record without causal claims?"></textarea></label><label>Next experimental steps<textarea name="nextSteps" rows="2" placeholder="What should be tried or measured next?"></textarea></label><div class="form-actions"><button type="button" class="text-button" data-action="back-experiment" data-id="${esc(experimentId)}">Cancel</button><button class="primary-button">Save evaluation</button></div></form>`;

  openDialog("record-dialog");
}

function showExperimentDetail(id) {
  const experiment = getExperiment(id); const revisions = state.revisions.filter(item => experiment.formulaRevisionIds.includes(item.id)); const batches = state.batches.filter(item => experiment.batchIds.includes(item.id)); const evaluations = state.evaluations.filter(item => experiment.evaluationIds?.includes(item.id)).sort((a, b) => String(a.evaluatedAt).localeCompare(String(b.evaluatedAt)) || a.id.localeCompare(b.id));
  $('#record-dialog-content').innerHTML = `<div class="dialog-content"><p class="label">${esc(experiment.experimentId)} · ${esc(experiment.status)}</p><h2>${esc(experiment.title)}</h2><p class="record-summary">${esc(experiment.objective)}</p><div class="chips"><span class="chip">${revisions.length} revisions</span><span class="chip">${batches.length} physical batches</span><span class="chip">${evaluations.length} evaluations</span></div><div class="form-actions"><button class="primary-button" data-action="new-revision" data-id="${esc(id)}">＋ Formula revision</button><button class="icon-button" data-action="new-batch" data-id="${esc(id)}">Record physical batch</button><button class="icon-button" data-action="new-evaluation" data-id="${esc(id)}">Record evaluation</button></div><h3>REVISION HISTORY</h3>${revisions.map(revision => `<div class="record"><strong>Revision ${esc(revision.revision)}</strong><span class="record-date"> · ${formatDate(revision.createdAt)}</span><p class="record-summary">${esc(revision.notes || 'No notes')}</p><div class="chips">${(revision.ingredients || []).map(item => `<span class="chip">${esc(item.materialName || item.materialId)} · ${esc(item.quantity)} ${esc(item.unit)}${item.lotId ? ` · lot ${esc(item.lotId)}` : ''}</span>`).join('')}</div></div>`).join('') || '<p class="muted">No revisions yet.</p>'}<h3>PHYSICAL BATCHES</h3>${batches.map(batch => { const summary = batchSummary(batch); return `<div class="record"><div class="record-top"><div><strong>${esc(batch.batchCode)}</strong><span class="record-date"> · ${formatDate(batch.mixingDate)}</span></div><button class="icon-button" data-action="open-batch" data-id="${esc(batch.id)}" data-experiment-id="${esc(experiment.id)}">Review batch</button></div><p class="record-summary">Revision ${esc(revisions.find(item => item.id === batch.formulaRevisionId)?.revision || '?')} · planned ${esc(batch.plannedAmount)} ${esc(batch.unit)} · actual ${esc(summary.totalAmount.toFixed(4))} ${esc(summary.unit)}</p></div>`; }).join('') || '<p class="muted">No physical batches yet. Planned formulas do not consume stock.</p>'}<h3>SENSORY TIMELINE</h3>${evaluations.length ? `<div class="evaluation-timeline">${evaluations.map(evaluation => `<article class="record"><div class="record-top"><div><strong>${esc(evaluation.intervalLabel || 'Unlabelled interval')}</strong><span class="record-date"> · ${formatDate(evaluation.evaluatedAt)}${evaluation.elapsedMinutes !== undefined ? ` · ${esc(evaluation.elapsedMinutes)} min` : ''}</span></div><span class="status ${statusClass(evaluation.provenance || (evaluation.isMeasured ? 'measured' : 'subjective'))}">${esc(evaluation.provenance || (evaluation.isMeasured ? 'measured' : 'subjective'))}</span></div><p class="record-summary">${esc(evaluation.medium || 'Medium unknown')} · ${esc(evaluation.environment || 'Environment unknown')} · ${esc(evaluation.conditions || 'Conditions not recorded')}</p><div class="chips">${(evaluation.descriptors || []).map(item => `<span class="chip">${esc(item)}</span>`).join('')}</div><p><strong>Subjective:</strong> ${esc(evaluation.subjectiveNotes || 'Not recorded')}</p>${evaluation.measuredResults ? `<p><strong>Measured:</strong> ${esc(evaluation.measuredResults)}</p>` : '<p class="muted"><strong>Measured:</strong> Not recorded</p>'}${evaluation.predictedOutcome ? `<p class="muted"><strong>Predicted:</strong> ${esc(evaluation.predictedOutcome)}</p>` : ''}<p class="muted">Longevity: ${esc(evaluation.longevityObservation || 'Not recorded')}${evaluation.longevityMethod ? ` · ${esc(evaluation.longevityMethod)}` : ''} · Projection: ${esc(evaluation.projectionObservation || 'Not recorded')}${evaluation.projectionMethod ? ` · ${esc(evaluation.projectionMethod)}` : ''}</p><p><strong>Conclusion:</strong> ${esc(evaluation.conclusions || 'Not recorded')}<br><strong>Next:</strong> ${esc(evaluation.nextSteps || 'Not recorded')}</p></article>`).join('')}</div>` : '<div class="empty-state">No evaluations yet. Record an opening, heart, dry-down, or custom interval from a physical batch.</div>'}</div>`;
  openDialog('record-dialog');
}

function renderCompareB5() {
  const records = state.revisions.map(revision => { const experiment = getExperiment(revision.experimentId); return { value: revision.id, label: `${experiment?.experimentId || 'Experiment'} · Revision ${revision.revision} · ${experiment?.title || ''}` }; }); const a = $('#compare-a'); const b = $('#compare-b'); const previousA = a.value; const previousB = b.value; const options = records.map(record => `<option value="${esc(record.value)}">${esc(record.label)}</option>`).join(''); a.innerHTML = options; b.innerHTML = options; a.value = records.some(record => record.value === previousA) ? previousA : records[0]?.value || ''; b.value = records.some(record => record.value === previousB) ? previousB : records[1]?.value || records[0]?.value || '';
  if (records.length < 2) { $('#comparison').innerHTML = '<div class="empty-state"><strong>Two formula revisions make a comparison.</strong>Create another revision to compare recorded evidence.</div>'; return; }
  const comparison = compareRevisions(state, a.value, b.value); const card = (revisionId, label, evaluations, batches) => `<article class="comparison-card"><p class="label">${esc(label)}</p><h2>${esc(getExperiment(revisionId ? state.revisions.find(item => item.id === revisionId)?.experimentId : '')?.title || 'Revision')}</h2><h3>BATCH EVIDENCE</h3>${batches.length ? batches.map(batch => `<div class="record"><strong>${esc(batch.batchCode)}</strong><p>Planned ${esc(batch.plannedAmount)} ${esc(batch.plannedUnit)} · actual ${batch.actual ? `${esc(batch.actual.totalAmount.toFixed(4))} ${esc(batch.actual.unit)}` : 'not recorded'}</p>${batch.plannedActual?.missingAdditions?.length ? '<span class="unknown-stock">Missing planned additions</span>' : ''}${batch.plannedActual?.extraAdditions?.length ? '<span class="unknown-stock">Extra actual additions</span>' : ''}</div>`).join('') : '<p class="muted">No physical batch linked; revision is not proof of a mixed batch.</p>'}<h3>SENSORY EVIDENCE</h3>${evaluations.length ? evaluations.map(evaluation => `<div class="record"><div class="record-top"><strong>${esc(evaluation.intervalLabel)}</strong><span class="status ${statusClass(evaluation.provenance)}">${esc(evaluation.provenance)}</span></div><p>${esc(evaluation.subjectiveNotes || 'No subjective notes recorded.')}</p>${evaluation.measuredResults ? `<p><strong>Measured:</strong> ${esc(evaluation.measuredResults)}</p>` : '<p class="muted">Measured result not recorded.</p>'}<p class="muted">${esc(evaluation.medium)} · ${esc(evaluation.environment)} · ${esc(evaluation.conditions)}</p></div>`).join('') : '<p class="muted">No evaluations linked to this revision or its batches.</p>'}</article>`;
  const ingredientChanges = comparison.ingredientChanges.length ? comparison.ingredientChanges.map(change => `<li>${esc(change.kind)} · ${esc(change.after?.materialName || change.before?.materialName || change.key)}</li>`).join('') : '<li>No ingredient changes recorded.</li>';
  $('#comparison').innerHTML = `${card(comparison.leftRevisionId, 'LEFT REVISION', comparison.leftEvaluations, comparison.leftBatchEvidence)}${card(comparison.rightRevisionId, 'RIGHT REVISION', comparison.rightEvaluations, comparison.rightBatchEvidence)}<div class="compare-note"><strong>WHAT CHANGED</strong><ul>${ingredientChanges}</ul><strong>CONDITIONS</strong><p>${comparison.conditionDifferences.length ? comparison.conditionDifferences.map(item => `${esc(item.field)} differs: ${esc(item.left.join(', '))} vs ${esc(item.right.join(', '))}`).join('<br>') : 'No recorded condition differences.'}</p><strong>WHAT CANNOT BE CONCLUDED</strong><p>${comparison.summary.cannotConclude.map(item => esc(item)).join(' ')}</p></div>`;
}

document.querySelectorAll('[data-screen]').forEach(button => button.addEventListener('click', () => { currentScreen = button.dataset.screen; document.querySelectorAll('.nav').forEach(item => item.classList.toggle('active', item === button)); document.querySelectorAll('[data-screen-panel]').forEach(panel => panel.classList.toggle('hidden', panel.id !== `screen-${currentScreen}`)); $('#breadcrumb').textContent = button.textContent.trim(); if (currentScreen === 'experiments') renderExperiments(); if (currentScreen === 'coach') renderCoachControls(); if (currentScreen === 'compare') renderCompareB5(); if (currentScreen === 'evaluations') renderEvaluationJournal(); if (currentScreen === 'materials') { try { renderMaterials(); } catch (error) { toast(`Inventory error: ${error.message}`); } } if (currentScreen === 'equipment') renderEquipment(); if (currentScreen === 'purchases') renderPurchases(); window.scrollTo({ top: 0, behavior: 'smooth' }); }));
document.querySelectorAll('[data-close]').forEach(button => button.addEventListener('click', () => closeDialog(button.dataset.close)));
document.addEventListener('click', event => {
  const action = event.target.closest('[data-action]'); if (!action) return;
  const type = action.dataset.action;
  if (type === 'new-journal') showJournalForm();
  if (type === 'new-experiment') { $('#experiment-form').reset(); openDialog('experiment-dialog'); }
   if (type === 'new-material') { $('#material-form').reset(); openDialog('material-dialog'); }
     if (type === 'new-equipment') showEquipmentForm();
     if (type === 'edit-equipment') showEquipmentForm(state.equipment.find(item => item.id === action.dataset.id));
     if (type === 'new-purchase') showPurchaseForm();
     if (type === 'edit-purchase') showPurchaseForm(state.purchases.find(item => item.id === action.dataset.id));
     if (type === 'add-purchase-line') { const rows = [...document.querySelectorAll('#purchase-lines .purchase-line-row')].map(row => rowValues(row)); rows.push({}); renderPurchaseLines(rows); }
     if (type === 'remove-purchase-line') { const rows = [...document.querySelectorAll('#purchase-lines .purchase-line-row')]; if (rows.length > 1) action.closest('.purchase-line-row').remove(); }
   if (type === 'new-verification') showVerificationForm(action.dataset.id);
   if (type === 'new-maintenance') showMaintenanceForm(action.dataset.id);
   if (type === 'new-measurement') showMeasurementForm(action.dataset.id);
   if (type === 'new-movement') { showMovementForm(action.dataset.materialId, action.dataset.lotId); }
   if (type === 'new-lot') { showLotForm(action.dataset.materialId); }
   if (type === 'reconcile-lot') { showReconcileForm(action.dataset.lotId); }
  if (type === 'open-journal') showJournalForm(state.journalEntries.find(item => item.id === action.closest('[data-journal-id]').dataset.journalId));
  if (type === 'duplicate-journal') { const source = state.journalEntries.find(item => item.id === action.closest('[data-journal-id]').dataset.journalId); showJournalForm({ ...source, id: '' , title: `${source.title} — copy` }); }
   if (type === 'new-revision') showRevisionForm(action.dataset.id);
   if (type === 'new-batch') showBatchForm(action.dataset.id);
   if (type === 'open-batch') showBatchDetail(action.dataset.id, action.dataset.experimentId);
    if (type === 'add-batch-addition') { const rows = [...document.querySelectorAll('#batch-additions .batch-addition-row')].map(row => ({ materialId: row.querySelector('[data-role="addition-material"]')?.value, materialLotId: row.querySelector('[data-role="addition-lot"]')?.value, amount: row.querySelector('[name="amount"]')?.value, unit: row.querySelector('[name="unit"]')?.value, purchaseLineItemId: row.querySelector('[name="purchaseLineItemId"]')?.value, concentration: row.querySelector('[name="concentration"]')?.value, addedAt: row.querySelector('[name="addedAt"]')?.value })); rows.push({}); renderBatchAdditionRows($('#batch-form'), rows); }
   if (type === 'remove-batch-addition') { const rows = [...document.querySelectorAll('#batch-additions .batch-addition-row')]; if (rows.length > 1) action.closest('.batch-addition-row').remove(); }
   if (type === 'new-evaluation') showSensoryEvaluationForm(action.dataset.id);
   if (type === 'generate-coach') runCoach();
  if (type === 'back-experiment') showExperimentDetail(action.dataset.id);
 });
document.addEventListener('change', event => {
  if (event.target.matches('[data-role="purchase-material"]')) {
    const row = event.target.closest('.purchase-line-row'); const material = state.materials.find(item => item.id === event.target.value); const lotSelect = row.querySelector('[data-role="purchase-lot"]'); lotSelect.innerHTML = (material?.lots || []).map(lot => `<option value="${esc(lot.id)}">${esc(lot.lotCode || lot.id)} · ${esc(lot.receivedUnit || '?')}</option>`).join(''); const lot = material?.lots?.[0]; row.querySelector('[name="purchaseLineItemId"]')?.remove(); if (lot) row.querySelector('[name="unit"]').value = lot.receivedUnit || 'g';
  }
  if (event.target.matches('[data-role="purchase-lot"]')) { const row = event.target.closest('.purchase-line-row'); const select = row.querySelector('[name="purchaseLineItemId"]'); if (select) select.innerHTML = purchaseLineOptions(event.target.value); }
  if (event.target.matches('[data-role="addition-material"]')) {
     const row = event.target.closest('.batch-addition-row'); const material = state.materials.find(item => item.id === event.target.value); const lotSelect = row.querySelector('[data-role="addition-lot"]'); lotSelect.innerHTML = (material?.lots || []).map(lot => `<option value="${esc(lot.id)}">${esc(lot.lotCode || lot.id)} · ${esc(lot.receivedUnit || stockStatus(state, lot.id).unit || '?')}</option>`).join(''); const lot = material?.lots?.[0]; if (lot) { row.querySelector('[name="unit"]').value = lot.receivedUnit || stockStatus(state, lot.id).unit || 'g'; row.querySelector('[name="purchaseLineItemId"]').innerHTML = purchaseLineOptions(lot.id); }
  }
  if (event.target.matches('[data-role="addition-lot"]')) { const row = event.target.closest('.batch-addition-row'); row.querySelector('[name="purchaseLineItemId"]').innerHTML = purchaseLineOptions(event.target.value); }
  if (event.target.id === 'batch-form-revision') {
    const revision = state.revisions.find(item => item.id === event.target.value); const rows = (revision?.ingredients || []).map(ingredient => ({ materialId: ingredient.materialId, materialLotId: ingredient.lotId || state.materials.find(item => item.id === ingredient.materialId)?.lots?.[0]?.id, amount: ingredient.quantity, unit: ingredient.unit, concentration: ingredient.stockConcentration ?? 100 })); renderBatchAdditionRows($('#batch-form'), rows.length ? rows : [{}]);
  }
});
persistence.subscribe(() => { try { state = persistence.load(); storageLocked = false; renderAll(); } catch (error) { storageLocked = true; toast(error.message); } });
$('#experiment-list').addEventListener('click', event => { const card = event.target.closest('[data-experiment-id]'); if (card) showExperimentDetail(card.dataset.experimentId); });
$('#journal-search').addEventListener('input', renderJournal); $('#journal-filter').addEventListener('change', renderJournal); $('#experiment-search').addEventListener('input', renderExperiments); $('#experiment-status').addEventListener('change', renderExperiments); $('#evaluation-search').addEventListener('input', renderEvaluationJournal); $('#evaluation-provenance').addEventListener('change', renderEvaluationJournal); $('#compare-a').addEventListener('change', renderCompareB5); $('#compare-b').addEventListener('change', renderCompareB5); $('#coach-experiment').addEventListener('change', () => { renderCoachControls(); $('#coach-output').innerHTML = '<div class="empty-state"><strong>Build a fresh debrief for this context.</strong><p>The Coach is read-only and uses only the selected records.</p></div>'; }); $('#coach-revision').addEventListener('change', () => {}); $('#coach-batch').addEventListener('change', () => {});

$('#journal-form').addEventListener('submit', event => { event.preventDefault(); const values = journalFormValues(event.target); const editId = event.target.dataset.editId; try { const next = editId ? updateJournalEntry(state, editId, values) : addJournalEntry(state, values); if (persist(next)) { closeDialog('journal-dialog'); toast(editId ? 'Journal entry updated' : 'Journal entry saved'); } } catch (error) { toast(error.message); } });
$('#experiment-form').addEventListener('submit', event => { event.preventDefault(); const next = addExperiment(state, Object.fromEntries(new FormData(event.target))); if (persist(next)) { closeDialog('experiment-dialog'); toast('Experiment created'); } });
function showMovementForm(materialId = '', lotId = '') { const form = $('#movement-form'); form.reset(); const materialSelect = $('#movement-material'); materialSelect.innerHTML = state.materials.map(material => `<option value="${esc(material.id)}">${esc(material.name)}</option>`).join(''); materialSelect.value = materialId || state.materials[0]?.id || ''; const updateLots = () => { const material = state.materials.find(item => item.id === materialSelect.value); $('#movement-lot').innerHTML = (material?.lots || []).map(lot => `<option value="${esc(lot.id)}">${esc(lot.lotCode || lot.id)} · ${esc(lot.receivedUnit || 'unit unknown')}</option>`).join(''); if (lotId && material?.lots?.some(lot => lot.id === lotId)) $('#movement-lot').value = lotId; const lot = material?.lots?.find(item => item.id === $('#movement-lot').value) || material?.lots?.[0]; if (lot) { form.elements.unit.value = lot.receivedUnit || stockStatus(state, lot.id).unit || ''; $('#movement-reference').innerHTML = '<option value="">Not required</option>' + state.stockMovements.filter(item => item.materialLotId === lot.id).map(item => `<option value="${esc(item.id)}">${esc(item.movementType)} · ${esc(item.quantity)} ${esc(item.unit)} · ${formatDate(item.occurredAt)}</option>`).join(''); } }; materialSelect.onchange = updateLots; $('#movement-lot').onchange = updateLots; updateLots(); openDialog('movement-dialog'); }
function showLotForm(materialId) { const form = $('#lot-form'); form.reset(); form.elements.materialId.value = materialId; $('#lot-material-name').textContent = `Adding a physical lot to ${state.materials.find(item => item.id === materialId)?.name || 'material'}.`; openDialog('lot-dialog'); }
function showReconcileForm(lotId) { const { material, lot } = state.materials.flatMap(item => (item.lots || []).map(candidate => ({ material: item, lot: candidate }))).find(item => item.lot.id === lotId) || {}; if (!lot) return; const form = $('#reconcile-form'); form.reset(); const status = stockStatus(state, lotId); form.elements.materialLotId.value = lotId; form.elements.recorded.value = status.balanceKnown ? `${status.balance.toFixed(4)} ${status.unit}` : 'Unknown — opening not established'; form.elements.unit.value = status.unit; $('#reconcile-lot-name').textContent = `${material.name} · ${lot.lotCode || lot.id}`; const quantityLabel = form.elements.physicalQuantity.closest('label'); quantityLabel.firstChild.textContent = status.balanceKnown ? 'Physical count' : 'Measured opening quantity'; $('#reconcile-variance').textContent = status.balanceKnown ? 'Enter a physical count to preview the variance.' : 'No trustworthy opening was recorded. Enter a measured opening quantity; historical consumption remains preserved.'; form.elements.physicalQuantity.disabled = false; form.elements.reason.disabled = false; form.querySelector('button.primary-button').disabled = false; openDialog('reconcile-dialog'); }
const localDateTime = value => value ? new Date(value).toISOString().slice(0, 16) : new Date().toISOString().slice(0, 16);
function showEquipmentForm(item = null) { const form = $('#equipment-form'); form.reset(); form.dataset.editId = item?.id || ''; form.elements.status.value = item?.status || 'available'; if (item) for (const key of ['name', 'equipmentType', 'manufacturer', 'model', 'serialNumber', 'location', 'status', 'acquiredAt', 'resolution', 'resolutionUnit', 'notes']) if (form.elements[key]) form.elements[key].value = item[key] ?? ''; $('#equipment-dialog h2').textContent = item ? 'Edit equipment' : 'Register equipment'; openDialog('equipment-dialog'); }
function showVerificationForm(equipmentId) { const item = state.equipment.find(candidate => candidate.id === equipmentId); if (!item) return; const form = $('#verification-form'); form.reset(); form.elements.equipmentId.value = equipmentId; form.elements.performedAt.value = localDateTime(); $('#verification-equipment-name').textContent = `${item.name} · verification remains unknown until evidence is recorded.`; openDialog('verification-dialog'); }
function showMaintenanceForm(equipmentId) { const item = state.equipment.find(candidate => candidate.id === equipmentId); if (!item) return; const form = $('#maintenance-form'); form.reset(); form.elements.equipmentId.value = equipmentId; form.elements.occurredAt.value = localDateTime(); form.elements.statusAfter.value = item.status === 'retired' ? 'retired' : 'under-maintenance'; $('#maintenance-equipment-name').textContent = item.name; openDialog('maintenance-dialog'); }
function showMeasurementForm(equipmentId) { const item = state.equipment.find(candidate => candidate.id === equipmentId); if (!item) return; const form = $('#measurement-form'); form.reset(); form.elements.equipmentId.value = equipmentId; form.elements.measuredAt.value = localDateTime(); form.elements.batchId.innerHTML = '<option value="">Not linked</option>' + state.batches.map(batch => `<option value="${esc(batch.id)}">${esc(batch.batchCode)}</option>`).join(''); form.elements.experimentId.innerHTML = '<option value="">Not linked</option>' + state.experiments.map(experiment => `<option value="${esc(experiment.id)}">${esc(experiment.experimentId)} · ${esc(experiment.title)}</option>`).join(''); form.elements.journalEntryId.innerHTML = '<option value="">Not linked</option>' + state.journalEntries.map(entry => `<option value="${esc(entry.id)}">${esc(entry.title)}</option>`).join(''); form.elements.evaluationId.innerHTML = '<option value="">Not linked</option>' + state.evaluations.map(evaluation => `<option value="${esc(evaluation.id)}">${esc(evaluation.intervalLabel || evaluation.id)} · ${formatDate(evaluation.evaluatedAt)}</option>`).join(''); $('#measurement-equipment-name').textContent = `${item.name} · compatible units are recorded as entered; no conversion is inferred.`; openDialog('measurement-dialog'); }
function purchaseLineOptions(lotId, selected = '') { const lines = state.purchaseLineItems.filter(line => line.materialLotId === lotId); return `<option value="">${lines.length ? 'Choose receipt price' : 'No purchase price recorded'}</option>${lines.map(line => { const purchase = state.purchases.find(item => item.id === line.purchaseId); return `<option value="${esc(line.id)}" ${line.id === selected ? 'selected' : ''}>${esc(purchase?.receiptNumber || line.purchaseId)} · ${esc(line.unitPrice)} ${esc(purchase?.currency || '')}/${esc(line.unit)}${purchase?.receiptEvidence ? '' : ' · unverified'}</option>`; }).join('')}`; }
function purchaseLineRow(index, values = {}) { const materials = state.materials.map(material => `<option value="${esc(material.id)}" ${material.id === values.materialId ? 'selected' : ''}>${esc(material.name)}</option>`).join(''); const material = state.materials.find(item => item.id === (values.materialId || state.materials[0]?.id)); const lots = (material?.lots || []).map(lot => `<option value="${esc(lot.id)}" ${lot.id === values.materialLotId ? 'selected' : ''}>${esc(lot.lotCode || lot.id)} · ${esc(lot.receivedUnit || '?')}</option>`).join(''); return `<div class="batch-addition-row purchase-line-row" data-purchase-line-index="${index}"><input name="id" type="hidden" value="${esc(values.id || '')}"><div class="form-grid"><label>Material<select name="materialId" data-role="purchase-material" required>${materials}</select></label><label>Lot<select name="materialLotId" data-role="purchase-lot" required>${lots}</select></label><label>Purchased quantity<input name="quantity" type="number" min="0.000001" step="any" value="${esc(values.quantity ?? '')}" required></label><label>Unit<select name="unit"><option value="mg" ${values.unit === 'mg' ? 'selected' : ''}>mg</option><option value="g" ${values.unit === 'g' || !values.unit ? 'selected' : ''}>g</option><option value="kg" ${values.unit === 'kg' ? 'selected' : ''}>kg</option><option value="mL" ${values.unit === 'mL' ? 'selected' : ''}>mL</option><option value="L" ${values.unit === 'L' ? 'selected' : ''}>L</option></select></label><label>Unit price<input name="unitPrice" type="number" min="0" step="0.000001" value="${esc(values.unitPrice ?? '')}" required></label><label>Line total<input name="lineTotal" type="number" min="0" step="0.000001" value="${esc(values.lineTotal ?? '')}" placeholder="Auto from quantity × price"></label></div><label>Notes<input name="notes" value="${esc(values.notes || '')}"></label><button type="button" class="text-button" data-action="remove-purchase-line">Remove line</button></div>`; }
function renderPurchaseLines(rows) { $('#purchase-lines').innerHTML = rows.map((values, index) => purchaseLineRow(index, values)).join(''); }
function showPurchaseForm(purchase = null) { const form = $('#purchase-form'); form.reset(); form.dataset.editId = purchase?.id || ''; form.existingEvidence = purchase?.receiptEvidence; form.elements.purchaseDate.value = purchase?.purchaseDate?.slice(0, 10) || today(); form.elements.currency.value = purchase?.currency || 'USD'; form.elements.discount.value = purchase?.discount ?? 0; form.elements.tax.value = purchase?.tax ?? 0; form.elements.shipping.value = purchase?.shipping ?? 0; if (purchase) { for (const key of ['supplier', 'receiptNumber', 'notes']) if (form.elements[key]) form.elements[key].value = purchase[key] || ''; form.elements.receiptReference.value = purchase.receiptEvidence?.kind === 'reference' ? purchase.receiptEvidence.reference : ''; renderPurchaseLines(state.purchaseLineItems.filter(line => line.purchaseId === purchase.id)); } else renderPurchaseLines([{}]); $('#purchase-dialog h2').textContent = purchase ? 'Edit purchase' : 'Record a purchase'; openDialog('purchase-dialog'); }
$('#movement-form').addEventListener('submit', event => { event.preventDefault(); const values = Object.fromEntries(new FormData(event.target)); try { const next = addStockMovement(state, { materialId: values.materialId, materialLotId: values.materialLotId, movementType: values.movementType, direction: values.direction, quantity: Number(values.quantity), unit: values.unit, referenceMovementId: values.referenceMovementId || undefined, verified: values.verified === 'on', confirmedReturn: values.confirmedReturn === 'on', occurredAt: values.occurredAt ? new Date(values.occurredAt).toISOString() : undefined, note: values.note }); if (persist(next)) { closeDialog('movement-dialog'); toast('Stock movement appended'); } } catch (error) { toast(error.message); } });
$('#reconcile-form').addEventListener('input', event => { if (event.target.name !== 'physicalQuantity') return; const form = event.currentTarget; const lotId = form.elements.materialLotId.value; const status = stockStatus(state, lotId); const physical = Number(form.elements.physicalQuantity.value); if (!Number.isFinite(physical) || physical < 0) { $('#reconcile-variance').textContent = 'Enter a valid non-negative quantity.'; return; } if (!status.balanceKnown) { $('#reconcile-variance').textContent = `Measured opening: ${physical.toFixed(4)} ${status.unit}. This will establish the opening and preserve prior history.`; return; } const variance = physical - status.balance; $('#reconcile-variance').textContent = `Variance: ${variance >= 0 ? '+' : ''}${variance.toFixed(4)} ${status.unit}. This will append a verified ${variance >= 0 ? 'increase' : 'decrease'} adjustment; history is not edited.`; $('#reconcile-variance').className = `result-card ${variance >= 0 ? 'variance-positive' : 'variance-negative'}`; });
